const query = ($('Trigger desde Agente').first().json.query || '').toLowerCase();

const knowledge = [
  {
    category: 'SERVICES',
    keywords: 'services solutions offerings what provide staffing augmentation',
    answer: 'MSI Technologies provides: IT Staff Augmentation (nearshore LATAM engineers), Cybersecurity, Cloud Computing (AWS/Azure/GCP), AI Solutions and Automation, BPO, and Nearshore Staffing. Our engineers are senior-level (5+ years), US timezone aligned, fluent in English, and ready to start in 2-4 weeks.'
  },
  {
    category: 'PRICING',
    keywords: 'price cost pricing rate salary budget expensive cheap savings',
    answer: 'MSI provides senior LATAM engineers at 20-35% below US domestic hiring rates. Typical savings: $40,000-$80,000 per year per engineer. Our model is flexible: staff augmentation (no long-term commitment), project-based, or retained dedicated teams. No relocation costs, no benefits burden on the client side.'
  },
  {
    category: 'STAFFING_ROLES',
    keywords: 'tech stack technology roles developer engineer java python react full stack cloud devops data qa mobile',
    answer: 'MSI staffs: Full-Stack (React, Node.js, Java, Python, .NET), Cloud and DevOps (AWS, Azure, GCP, Kubernetes, Terraform), Data Engineering and AI/ML, Cybersecurity, QA and Automation Testing, Mobile (iOS/Android), and 5G/IoT specialists. Typical experience: 5-10 years. All candidates pass a technical screening and English proficiency assessment.'
  },
  {
    category: 'PROCESS',
    keywords: 'process timeline onboard start how long weeks ramp hire interview',
    answer: 'MSI process: 1) 30-minute requirements call with Nataly Riano. 2) MSI presents 2-3 pre-screened candidates within one week. 3) Client conducts brief interviews. 4) Selected engineer onboards in 2-4 weeks. No recruitment fee — MSI manages payroll, benefits, and HR in Latin America. Client pays a monthly service fee only for active engineers.'
  },
  {
    category: 'OBJECTION_VENDOR',
    keywords: 'vendor partner outsource already have competitor other provider',
    answer: 'Many MSI clients supplement existing vendors with MSI for specialized roles or to fill gaps that are hard to source. MSI engineers are consistently rated higher quality than typical outsourcing because we focus on senior talent with true US timezone alignment. A short pilot project is the easiest way to compare the difference.'
  },
  {
    category: 'OBJECTION_FREEZE',
    keywords: 'freeze budget no hiring not right now not looking recession cut',
    answer: "MSI's contractor model is designed for exactly this scenario — engineers are contractors, not FTEs, so they don't affect headcount or trigger HR approval processes. Many companies use MSI for project-based work during hiring freezes without any long-term commitment. It gives full flexibility to scale up or down with no permanent obligation."
  },
  {
    category: 'OBJECTION_INTERNAL',
    keywords: 'internal team in house build our own handle ourselves',
    answer: 'MSI works alongside internal teams — we complement them for specialized skills or capacity that is hard to recruit quickly. Most clients use MSI to accelerate projects that would otherwise take 3-6 months to staff internally. Our engineers integrate directly into existing workflows, Slack, Jira, and sprint cycles.'
  },
  {
    category: 'SOCIAL_PROOF',
    keywords: 'client customer reference case study who worked portfolio trust experience',
    answer: 'MSI has served 300+ companies across North America, including Fortune 500 enterprises, fast-growing tech startups, and financial services firms. Clients span Telecom, Fintech, Healthcare IT, E-commerce, and SaaS. MSI maintains strict confidentiality around client names, but Nataly can share relevant anonymized case studies in a discovery call.'
  },
  {
    category: 'AI_SOLUTIONS',
    keywords: 'ai artificial intelligence automation ml machine learning chatbot llm openai generative workflow',
    answer: "MSI's AI practice covers: Process Automation (RPA + AI), Custom LLM integration and fine-tuning, AI-powered chatbots and virtual assistants, Computer vision and document processing, Predictive analytics and data pipelines, and AI strategy consulting. All solutions are built by senior engineers with hands-on ML and AI production experience."
  },
  {
    category: 'CYBERSECURITY',
    keywords: 'security cyber cybersecurity compliance soc pentest vulnerability breach attack iso hipaa',
    answer: 'MSI Cybersecurity services: Security Operations Center (SOC) staffing, Penetration testing and vulnerability assessments, Compliance consulting (SOC2, ISO 27001, HIPAA, PCI-DSS), Cloud security architecture (AWS, Azure), Identity and Access Management, and Security code review. MSI security engineers hold certifications including CISSP, CISM, CEH, and CompTIA Security+.'
  },
  {
    category: 'CLOUD',
    keywords: 'cloud aws azure gcp google devops kubernetes docker terraform infrastructure migration',
    answer: 'MSI Cloud and DevOps services: Cloud migration and modernization (AWS, Azure, GCP), Infrastructure as Code (Terraform, Pulumi), Container orchestration (Kubernetes, Docker), CI/CD pipeline design, Site Reliability Engineering (SRE), and FinOps cost optimization. MSI cloud engineers hold active AWS, Azure, and GCP certifications.'
  },
  {
    category: 'COMPANY',
    keywords: 'company msi about who are you background history founded offices location headquarters',
    answer: 'MSI Technologies is a multinational IT solutions company with 20+ years of experience, 700+ active consultants, and 14 offices across the Americas including US, Colombia, Mexico, Argentina, Brazil, and Chile. Founded in 2003, MSI specializes in connecting North American companies with top-tier LATAM engineering talent. US headquarters: Miami, FL.'
  },
  {
    category: 'FINTECH',
    keywords: 'fintech finance financial banking payment transaction fraud risk compliance',
    answer: 'MSI has deep fintech experience: Payment processing systems, Core banking integration, Fraud detection with ML, Regulatory compliance (PCI-DSS, SOX), Open banking APIs, and Digital wallet infrastructure. Many MSI engineers come from fintech backgrounds and understand both the technical and regulatory requirements of financial services.'
  },
  {
    category: 'HEALTHCARE',
    keywords: 'healthcare health medical hospital ehr emr hipaa patient data health tech',
    answer: 'MSI supports healthcare IT including: EHR/EMR integration and development, HIPAA-compliant infrastructure, HL7 and FHIR API implementation, Telehealth platform development, Healthcare analytics, and Medical device software. MSI engineers with healthcare backgrounds understand clinical workflows and compliance requirements.'
  },
  {
    category: 'TELECOM',
    keywords: 'telecom telecommunications 5g lte network nfv sdn carrier mobile wireless',
    answer: 'MSI has specialized 5G and telecom engineers covering: 5G network implementation, Network Function Virtualization (NFV), Software Defined Networking (SDN), BSS/OSS systems, IoT connectivity platforms, and telecom API development. MSI is one of the few staffing firms with a dedicated telecom/5G practice in Latin America.'
  }
];

const queryWords = query.split(/\s+/).filter(w => w.length >= 3);
const results = [];

for (const item of knowledge) {
  const searchText = (item.keywords + ' ' + item.category).toLowerCase();
  let score = 0;
  for (const word of queryWords) {
    if (searchText.includes(word)) score += 2;
    if (item.answer.toLowerCase().includes(word)) score += 1;
  }
  if (score > 0) results.push({ ...item, score });
}

results.sort((a, b) => b.score - a.score);
const topResults = results.slice(0, 2);

if (topResults.length === 0) {
  return [{ json: {
    response: "For specific questions beyond standard MSI services, I recommend offering to connect the lead with Nataly Riano who can provide tailored information in a discovery call.",
    categories: []
  }}];
}

return [{ json: {
  response: topResults.map(r => r.answer).join('\n\n'),
  categories: topResults.map(r => r.category)
}}];
